pub(crate) fn preload(
    runtime: &mut RuntimeProcess,
    module: &str,
    authorization: &str,
) -> JsonValue {
    runtime.request(json!({
        "command": "preload",
        "module_cid": module,
        "authorization": authorization,
    }))
}

pub(crate) fn activate(
    runtime: &mut RuntimeProcess,
    module: &str,
    record: &str,
    source_module: &str,
    epoch: u64,
    authorization: &str,
) -> JsonValue {
    runtime.request(json!({
        "command": "activate",
        "module_cid": module,
        "expected_record_cid": record,
        "expected_module_cid": source_module,
        "expected_epoch": epoch,
        "authorization": authorization,
    }))
}

pub(crate) fn rollback(
    runtime: &mut RuntimeProcess,
    record: &str,
    module: &str,
    epoch: u64,
) -> JsonValue {
    runtime.request(json!({
        "command": "rollback",
        "expected_record_cid": record,
        "expected_module_cid": module,
        "expected_epoch": epoch,
        "authorization": AUTHORITY,
    }))
}

